properties.query:
let windowSize = 2h;

// S34: Recon/Credential Probe (연결키: Operator)
let S34 =
    UAVOpAudit_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType == 'login_failure';
// S95: Exfil Staging — UAVSatcomLink_CL 전역 게이트 (대용량 페이로드)
let S95Time = toscalar(
    UAVSatcomLink_CL
    | where TimeGenerated > ago(windowSize)
    | where PayloadBytes > 1000000
    | summarize min(TimeGenerated));
// S93: Bulk SAR/Imagery Exfil — UAVSarPayload_CL 전역 게이트
let S93Time = toscalar(
    UAVSarPayload_CL
    | where TimeGenerated > ago(windowSize)
    | where SizeBytes > 1000000
    | summarize min(TimeGenerated));
S34
| extend HasS95 = isnotnull(S95Time), HasS93 = isnotnull(S93Time)
| where HasS95 or HasS93
| extend CampaignType = "C12_자격증명_스테이징_대량유출"
| extend StepSummary = strcat("S34@", tostring(TimeGenerated), " | S95(전역)@", tostring(S95Time), " | S93(전역)@", tostring(S93Time))
| extend Severity = "High"
| project TimeGenerated, S95Time, S93Time, Operator, CampaignType, StepSummary, Severity
